for(const e of secondary.filter(e=>e.subject==='English')){
 const anchor=englishAnchors[e.title]||'';
 D('English',e.sourceBook,e.title,englishFiles[e.title],{
  overview:e.summary+' '+anchor,
  concepts:conceptPairs(e.keyPoints,anchor),
  reasoning:['State a focused interpretation of the exact question.','Select one or two precise incidents, images or structural choices from this text.','Explain how that evidence develops character, tone, conflict or theme; do not stop at naming it.','End by returning to the wording of the question rather than retelling the ending.'],
  visuals:['Make a compact map of situation → turning point → consequence.','For poems, track image/contrast → feeling → larger idea; for prose, track character choice → evidence → effect.'],
  examTips:['Use brief, accurate references in your own words instead of long quotation.','Distinguish summary (“what happens”) from analysis (“how and why it matters”).','Do not force a memorised moral onto a question that asks about character, tone or technique.'],
  distinctions:[anchor,'Narrator or speaker is a constructed voice and should not automatically be equated with the author.'],
  quickRevision:e.keyPoints,vocabulary:vocabByBook[e.sourceBook],
  selfCheck:[`What is the central tension or change in ${e.title}?`,'Which two details best support its main idea?','How does one language or structural choice shape the reader’s response?','What tempting plot-summary answer should be turned into analysis?']
 });
}

